//! The golden corpus: what the scrubber decides, pinned.
//!
//! `parsers_never_panic` proves the parsers survive hostile input. This proves
//! they still make the *same* decisions: every fixture's segments, categories,
//! and the exact bytes left after each removal profile. A change here is either
//! a bug or a deliberate policy change, and both deserve to be visible in a
//! diff rather than discovered by a user.
//!
//! Fixtures are generated by `generate.py` in this directory — synthesized,
//! never downloaded, so there is no third-party licence anywhere near the
//! corpus. Regenerate expectations deliberately:
//!
//! ```bash
//! python3 generate.py                          # if the bytes themselves change
//! MELLIVORA_GOLDEN_UPDATE=1 cargo test -p mellivora-scrub --test golden_corpus
//! ```

use std::fs;
use std::path::{Path, PathBuf};

use mellivora_scrub::{handler_for, RemovalPolicy};
use serde_json::{json, Value};
use sha2::{Digest, Sha256};

const PROFILES: [&str; 3] = ["privacy", "sharing", "archive"];

fn golden_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/golden")
}

fn fixtures() -> Vec<(String, Vec<u8>)> {
    let dir = golden_dir().join("fixtures");
    let mut files = Vec::new();
    for entry in fs::read_dir(&dir).unwrap_or_else(|error| panic!("{}: {error}", dir.display())) {
        let path = entry.expect("entry").path();
        if path.is_file() {
            let name = path
                .file_name()
                .expect("name")
                .to_string_lossy()
                .to_string();
            files.push((name, fs::read(&path).expect("read fixture")));
        }
    }
    files.sort();
    assert!(!files.is_empty(), "no fixtures in {}", dir.display());
    files
}

fn sha256_hex(bytes: &[u8]) -> String {
    let mut hasher = Sha256::new();
    hasher.update(bytes);
    hasher
        .finalize()
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}

/// Everything worth pinning about one fixture.
fn describe(name: &str, bytes: &[u8]) -> Value {
    let handler = handler_for(bytes).unwrap_or_else(|error| panic!("{name}: {error}"));
    let scan = handler
        .scan(bytes)
        .unwrap_or_else(|error| panic!("{name}: scan failed: {error}"));

    let segments: Vec<Value> = scan
        .segments
        .iter()
        .map(|segment| {
            json!({
                "kind": segment.kind,
                "category": segment.category.as_str(),
                "size": segment.size,
            })
        })
        .collect();

    let mut profiles = serde_json::Map::new();
    for profile in PROFILES {
        let policy = RemovalPolicy::profile(profile).expect("known profile");
        let stripped = handler
            .strip_with(bytes, &policy)
            .unwrap_or_else(|error| panic!("{name}/{profile}: strip failed: {error}"));
        profiles.insert(
            profile.to_string(),
            json!({
                "removed_bytes": scan.removable_bytes(&policy),
                "stripped_bytes": stripped.len(),
                "stripped_sha256": sha256_hex(&stripped),
            }),
        );
    }

    json!({
        "file": name,
        "format": scan.format.as_str(),
        "total_bytes": bytes.len(),
        "metadata_bytes": scan.metadata_bytes,
        "segments": segments,
        "profiles": profiles,
    })
}

fn actual() -> Value {
    let mut fixtures: Vec<Value> = fixtures()
        .iter()
        .map(|(name, bytes)| describe(name, bytes))
        .collect();
    fixtures.sort_by_key(|fixture| fixture["file"].as_str().unwrap_or_default().to_string());
    json!({
        "comment": "Generated by generate.py plus MELLIVORA_GOLDEN_UPDATE=1. \
                    A change here is a change in what metadata-strip decides.",
        "fixtures": fixtures,
    })
}

fn expected_path() -> PathBuf {
    golden_dir().join("expected.json")
}

#[test]
fn the_corpus_decides_what_it_used_to() {
    let actual = actual();

    if std::env::var_os("MELLIVORA_GOLDEN_UPDATE").is_some() {
        fs::write(
            expected_path(),
            format!(
                "{}\n",
                serde_json::to_string_pretty(&actual).expect("serialize")
            ),
        )
        .expect("write expected.json");
        eprintln!("rewrote {}", expected_path().display());
        return;
    }

    let expected: Value = serde_json::from_str(
        &fs::read_to_string(expected_path())
            .unwrap_or_else(|error| panic!("{}: {error}", expected_path().display())),
    )
    .expect("expected.json parses");

    let expected_fixtures = expected["fixtures"].as_array().expect("fixtures array");
    let actual_fixtures = actual["fixtures"].as_array().expect("fixtures array");

    let names = |value: &Vec<Value>| -> Vec<String> {
        value
            .iter()
            .map(|fixture| fixture["file"].as_str().unwrap_or_default().to_string())
            .collect()
    };
    assert_eq!(
        names(actual_fixtures),
        names(expected_fixtures),
        "the fixture list changed; add or remove entries in expected.json deliberately"
    );

    for (actual, expected) in actual_fixtures.iter().zip(expected_fixtures) {
        let file = actual["file"].as_str().unwrap_or_default();
        assert_eq!(
            actual, expected,
            "{file}: scan decisions or stripped bytes differ from the golden corpus"
        );
    }
}

#[test]
fn stripping_is_idempotent_and_never_grows_a_file() {
    for (name, bytes) in fixtures() {
        let handler = handler_for(&bytes).unwrap_or_else(|error| panic!("{name}: {error}"));
        for profile in PROFILES {
            let policy = RemovalPolicy::profile(profile).expect("known profile");
            let once = handler
                .strip_with(&bytes, &policy)
                .unwrap_or_else(|error| panic!("{name}/{profile}: {error}"));

            assert!(
                once.len() <= bytes.len(),
                "{name}/{profile}: stripping grew the file ({} → {})",
                bytes.len(),
                once.len()
            );

            // Stripping a stripped file must be a no-op: a second pass that
            // produces different bytes means the first pass left something the
            // reader cannot recognise.
            let twice = handler
                .strip_with(&once, &policy)
                .unwrap_or_else(|error| panic!("{name}/{profile}: second strip: {error}"));
            assert_eq!(once, twice, "{name}/{profile}: stripping is not idempotent");
        }
    }
}

#[test]
fn what_a_strip_keeps_needs_no_second_strip() {
    for (name, bytes) in fixtures() {
        let handler = handler_for(&bytes).unwrap_or_else(|error| panic!("{name}: {error}"));
        for profile in ["privacy", "sharing"] {
            let policy = RemovalPolicy::profile(profile).expect("known profile");
            let stripped = handler
                .strip_with(&bytes, &policy)
                .unwrap_or_else(|error| panic!("{name}/{profile}: {error}"));
            let rescan = handler
                .scan(&stripped)
                .unwrap_or_else(|error| panic!("{name}/{profile}: rescan: {error}"));
            assert_eq!(
                rescan.removable_bytes(&policy),
                0,
                "{name}/{profile}: the strip left metadata the policy would remove"
            );
        }
    }
}

#[test]
fn no_policy_can_reach_structure_or_colour() {
    // Byte-level strip only ever removes what the category says it may. If a
    // structural or colour segment were ever planned for removal, the file
    // would stop decoding — so this is the property that keeps stripping safe.
    for (name, bytes) in fixtures() {
        let handler = handler_for(&bytes).unwrap_or_else(|error| panic!("{name}: {error}"));
        let scan = handler.scan(&bytes).expect("scan");

        for profile in PROFILES {
            let policy = RemovalPolicy::profile(profile).expect("known profile");
            for segment in scan.segments.iter().filter(|s| !s.category.is_removable()) {
                assert!(
                    !policy.should_remove(segment),
                    "{name}/{profile}: {} ({}) is load-bearing but was planned for removal",
                    segment.kind,
                    segment.category
                );
            }
        }

        // And a policy that removes nothing must be a byte-for-byte no-op.
        let untouched = handler
            .strip_with(&bytes, &RemovalPolicy::none())
            .unwrap_or_else(|error| panic!("{name}: {error}"));
        assert_eq!(untouched, bytes, "{name}: a keep-everything policy changed the file");
    }
}
